WITH gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) > INTERVAL 90 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM transactions), sessions_transactions AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT DATE_TRUNC('MONTH', txn_time) AS activity_month, DATE_TRUNC('QUARTER', txn_time) AS quarter_start, MIN(txn_time) AS first_seen, SUM(amount) AS total_amount, MAX(txn_time) AS last_txn_time, ROUND(AVG(new_group_flag), 2) AS avg_new_group_flag, COUNT(*) FILTER (WHERE txn_type = 'REFUND') AS refund_rows, GROUPING(DATE_TRUNC('MONTH', txn_time)) AS grouping_level FROM sessions_transactions GROUP BY GROUPING SETS ((DATE_TRUNC('MONTH', txn_time), DATE_TRUNC('QUARTER', txn_time)), (DATE_TRUNC('MONTH', txn_time)));
